(()=>{'use strict';const $=s=>document.querySelector(s),el=(t,s)=>{const n=document.createElement(t);n.textContent=s;return n;},iso=n=>new Date(n).toISOString().slice(0,10),today=()=>iso(Date.now()+10800000),add=(d,n)=>iso(Date.parse(d)+n*86400000),monday=d=>add(d,-((new Date(d).getUTCDay()+6)%7)),label=d=>new Date(d+'T12:00:00Z').toLocaleDateString('ru-RU',{timeZone:'Europe/Moscow',weekday:'short',day:'numeric',month:'short'});
let week=add(monday(today()),7),data,selected,busy=false,loading=false;
async function api(body){const r=await fetch('/api/admin/schedule'+(body?'':'?week='+week),{cache:'no-store',...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw Error(d.error||'Не удалось сохранить.');return d;}
const hours=(s,e)=>s&&e?s+'–'+e:s?'с '+s:e?'до '+e:'';
function cell(person,day){const r=data.rows.find(x=>x.user_id===person.id&&x.day===day)||{revision:0,preference:'none',confirmed:0},b=el('button','');b.className='schedule-cell'+(r.confirmed?' approved':r.preference==='want'?' wanted':r.preference==='cannot'?' unavailable':'')+(person.id===data.user.id?' mine':'');b.type='button';b.append(el('span',person.name),el('strong',r.confirmed?'✓ Подтверждён':r.preference==='want'?'○ Хочу выйти':r.preference==='cannot'?'− Не могу':'—'));const time=hours(r.confirmed?r.plan_start:r.wish_start,r.confirmed?r.plan_end:r.wish_end);if(time)b.append(el('small',time));const note=r.confirmed?r.plan_note:r.wish_note;if(note)b.append(el('small',note));if(r.pending)b.append(el('small','⚠ Просьба изменить: '+({want:'хочу выйти',cannot:'не могу',none:'пока не знаю'}[r.preference])+' '+hours(r.wish_start,r.wish_end)+(r.wish_note?' · '+r.wish_note:'')));b.setAttribute('aria-label',person.name+', '+label(day)+': '+b.textContent);b.disabled=day<data.today||data.user.role!=='admin'&&person.id!==data.user.id;b.onclick=()=>edit(person,day,r);return b;}
function render(){const days=Array.from({length:7},(_,i)=>add(week,i));$('#week-label').textContent=label(days[0])+' — '+label(days[6]);const root=$('#schedule-grid');root.replaceChildren();const table=el('div','');table.className='schedule-table';const head=el('div','');head.className='schedule-row';head.append(el('strong','Сотрудник'));for(const day of days){const h=el('strong',label(day));h.append(el('small','Подтверждено: '+data.rows.filter(x=>x.day===day&&x.confirmed&&data.people.some(p=>p.id===x.user_id)).length));head.append(h);}table.append(head);for(const person of data.people){const row=el('div','');row.className='schedule-row'+(person.id===data.user.id?' own-row':'');row.append(el('strong',person.name));for(const day of days)row.append(cell(person,day));table.append(row);}root.append(table);const mobile=el('div','');mobile.className='schedule-days';for(const day of days){const section=el('section','');section.append(el('h2',label(day)+' · '+data.rows.filter(x=>x.day===day&&x.confirmed&&data.people.some(p=>p.id===x.user_id)).length+' подтверждено'));for(const p of [...data.people].sort((a,b)=>(b.id===data.user.id)-(a.id===data.user.id)))section.append(cell(p,day));mobile.append(section);}root.append(mobile);}
async function load(){if(loading)return;loading=true;const requested=week;try{const result=await api();if(requested!==week)return;data=result;$('#schedule-access-note').hidden=!data.user.scheduleOnly;render();$('#schedule-notice').textContent='';}catch(e){$('#schedule-notice').textContent=e.message;}finally{loading=false;if(requested!==week)load();}}
function edit(p,day,r){selected={p,day,r};$('#edit-title').textContent=p.name+' · '+label(day);const owner=data.user.role==='admin',self=p.id===data.user.id;$('#preference').closest('label').hidden=!self;$('#preference').value=r.preference==='none'?'want':r.preference;$('#start').value=(owner&&r.confirmed&&!r.pending?r.plan_start:r.wish_start)||'';$('#end').value=(owner&&r.confirmed&&!r.pending?r.plan_end:r.wish_end)||'';$('#note').value=(owner&&r.confirmed&&!r.pending?r.plan_note:r.wish_note)||'';$('#approved-note').textContent=r.confirmed?'Назначен выход '+hours(r.plan_start,r.plan_end)+'. Пожелание не отменяет назначение до решения администратора.':r.preference==='cannot'?'Сотрудник отметил: не могу. '+(r.wish_note||''):r.wish_note||'';$('#save-wish').hidden=!self;$('#save-wish').textContent=r.confirmed?'Запросить изменение':'Сохранить пожелание';$('#confirm-plan').hidden=!owner;$('#cancel-plan').hidden=!owner||!r.confirmed;$('#reject-request').hidden=!owner||!r.pending;$('#replacement-controls').hidden=true;$('#show-replacement').hidden=!owner||!r.confirmed;$('#edit-error').textContent='';$('#schedule-editor').showModal();}
async function save(action){if(busy)return;const {p,day,r}=selected;if(action==='confirm'&&r.preference==='cannot'&&!confirm('Сотрудник отметил, что не может выйти. Всё равно назначить?'))return;if(action==='cancel'&&!confirm('Снять назначение сотрудника '+p.name+' на '+label(day)+'?'))return;busy=true;$('#schedule-form').querySelectorAll('button,input,select').forEach(b=>b.disabled=true);try{await api({action,userId:p.id,day,revision:r.revision,preference:$('#preference').value,start:$('#start').value,end:$('#end').value,note:$('#note').value});$('#schedule-editor').close();await load();}catch(e){$('#edit-error').textContent=e.message+' Закройте окно и обновите график перед повтором.';}finally{busy=false;$('#schedule-form').querySelectorAll('button,input,select').forEach(b=>b.disabled=false);}}
for(const [id,action] of [['save-wish','wish'],['confirm-plan','confirm'],['cancel-plan','cancel'],['reject-request','reject']])$('#'+id).onclick=()=>save(action);
$('#close-editor').onclick=()=>$('#schedule-editor').close();$('#schedule-editor').addEventListener('cancel',e=>{if(busy)e.preventDefault();});$('#schedule-editor').addEventListener('close',()=>load());$('#schedule-form').onsubmit=e=>e.preventDefault();$('#previous').onclick=()=>{week=add(week,-7);load();};$('#next').onclick=()=>{week=add(week,7);load();};$('#this-week').onclick=()=>{week=monday(today());load();};$('#next-week').onclick=()=>{week=add(monday(today()),7);load();};setInterval(()=>{if(!document.hidden&&!$('#schedule-editor').open)load();},30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!$('#schedule-editor').open)load();});load();
})();

$('#show-replacement').onclick=()=>{
 const root=$('#replacement-person');root.replaceChildren();
 for(const p of data.people.filter(p=>p.id!==selected.p.id&&!data.rows.some(r=>r.user_id===p.id&&r.day===selected.day&&r.confirmed))){const option=el('option',p.name);option.value=p.id;root.append(option);}
 $('#replacement-controls').hidden=false;$('#replace-person').disabled=!root.options.length;
};
$('#replace-person').onclick=async()=>{
 if(busy)return;const replacementId=Number($('#replacement-person').value),target=data.rows.find(r=>r.user_id===replacementId&&r.day===selected.day);
 if(!replacementId)return;busy=true;$('#schedule-form').querySelectorAll('button,input,select').forEach(b=>b.disabled=true);
 try{await api({action:'replace',userId:selected.p.id,day:selected.day,revision:selected.r.revision,replacementId,replacementRevision:target?.revision||0});$('#schedule-editor').close();await load();}
 catch(e){$('#edit-error').textContent=e.message;}finally{busy=false;$('#schedule-form').querySelectorAll('button,input,select').forEach(b=>b.disabled=false);}
};
